//! 仕様の全チェック。項目は仕様の並びのまま。

use ui_api::{Chord, Key, Modifiers};

use super::{Check, Kind};

fn m(ctrl: bool, alt: bool, shift: bool, key: Key) -> Chord {
    Chord::new(
        key,
        Modifiers {
            ctrl,
            alt,
            shift,
            meta: false,
        },
    )
}

fn c(ch: char) -> Key {
    Key::Character(ch)
}

fn n(name: &'static str) -> Key {
    Key::Named(name.to_string())
}

pub struct Binding {
    pub alternatives: Vec<Chord>,
    pub sequence: Vec<Chord>,
}

fn b(alternatives: Vec<Chord>) -> Binding {
    Binding {
        alternatives,
        sequence: Vec::new(),
    }
}

fn s(sequence: Vec<Chord>) -> Binding {
    Binding {
        alternatives: Vec::new(),
        sequence,
    }
}

fn e() -> Binding {
    Binding {
        alternatives: Vec::new(),
        sequence: Vec::new(),
    }
}

